class Solution {
public:
    vector<int> finalArray(vector<int>& nums) {
        vector<int> st;
        for (int x : nums) {
            st.push_back(x);
            while (st.size() > 1 && st.back() == st[st.size()-2]) {
                st.pop_back();
                st.back() *= 2;
            }
        }
        return st;
    }
};

