class Solution {
    public int[] finalArray(int[] nums) {
        Deque<Long> st = new ArrayDeque<>();
        for (int x : nums) {
            st.push((long) x);
            while (st.size() > 1) {
                long a = st.poll(), b = st.peek();
                if (a == b) { st.poll(); st.push(a * 2); }
                else { st.push(a); break; }
            }
        }
        int[] res = new int[st.size()];
        for (int i = res.length - 1; i >= 0; i--) res[i] = st.poll().intValue();
        return res;
    }
}

